def get_related_pages_it(slug, limit=4):
    """Get related pages for internal linking (Italian)."""
    related = []
    for cluster_name, pages in CLUSTERS_IT.items():
        if slug in pages:
            for p in pages:
                if p != slug and p in SEO_PAGES_IT:
                    related.append({"slug": p, "title": SEO_PAGES_IT[p]["headline"]})

    if len(related) < limit:
        for s, page in SEO_PAGES_IT.items():
            if s != slug and not any(r["slug"] == s for r in related):
                related.append({"slug": s, "title": page["headline"]})
                if len(related) >= limit:
                    break

    return related[:limit]
